declare(strict_types=1);

// Profiles describe the circuit independently of saved setups.
return [
    'australia-albert-park' => ['5,278', 14, t('Media-alta'), t('rápido y fluido, con cambios de dirección y curvas de velocidad media y alta. La curva 3 es un giro lento; tras la 6 se enlaza una sección rápida que desemboca en las curvas 9 y 10. El asfalto puede estar deslizante al principio y ganar agarre a medida que se rueda.'), t('las curvas rápidas requieren un coche estable y apoyo aerodinámico, mientras las zonas de aceleración favorecen la velocidad en recta. La frenada y la salida de las curvas lentas afectan a la velocidad que se lleva al siguiente tramo.'), [['title' => 'Fórmula 1 — Albert Park', 'url' => 'https://www.formula1.com/en/racing/2025/australia', 'accessedAt' => '2026-11-08'], ['title' => 'OverTake — guía de curvas', 'url' => 'https://www.overtake.gg/news/f1-25-track-guides.3245/?full=1', 'accessedAt' => '2026-11-08'], ['title' => 'estudio de configuraciones aerodinámicas', 'url' => 'https://aisberg.unibg.it/retrieve/e40f7b88-612b-afca-e053-6605fe0aeaf2/TDUnibg_Ravelli-Umberto.pdf', 'accessedAt' => '2026-11-08']]],
    'china-shanghai' => ['5,451', 16, t('Media-alta'), t('combina curvas largas y enlazadas con una recta de 1,2 km. La primera secuencia se cierra progresivamente, las curvas 7 y 8 generan fuertes apoyos y la recta termina en una frenada para una horquilla lenta.'), t('las curvas prolongadas exigen agarre y equilibrio; la recta larga da mucho peso a la resistencia aerodinámica y a la estabilidad al frenar. El reasfaltado de 2025 aumentó el agarre; las curvas largas cargan especialmente el neumático delantero izquierdo.'), [['title' => 'Fórmula 1 — Shanghai', 'url' => 'https://www.formula1.com/en/racing/2025/china', 'accessedAt' => '2026-11-08'], ['title' => 'Fórmula 1 — guía del circuito', 'url' => 'https://www.formula1.com/en/latest/article/circuit-guide-everything-you-need-to-know-about-the-shanghai-international.1b0f0ghbsPMRsHJoHTt6eB.1b0f0ghbsPMRsHJoHTt6eB', 'accessedAt' => '2026-11-08']]],
    'japan-suzuka' => ['5,807', 18, t('Media-alta'), t('rápido y técnico. Las eses del primer sector enlazan cambios de dirección; Degner y 130R son secciones rápidas, mientras la horquilla y la chicane final reducen la velocidad.'), t('el apoyo y la estabilidad importan en las eses y los giros rápidos; también hay que conservar eficiencia para los tramos a fondo. Los apoyos prolongados castigan los neumáticos, pero Brembo clasifica el circuito entre los menos exigentes para los frenos.'), [['title' => 'Fórmula 1 — Suzuka', 'url' => 'https://www.formula1.com/en/racing/2025/japan', 'accessedAt' => '2026-11-08'], ['title' => 'Brembo — exigencia de frenos', 'url' => 'https://www.brembo.com/es/motorsport/formula1/circuitos-desafiantes', 'accessedAt' => '2026-11-08']]],
    'bahrain' => ['5,412', 15, t('Media'), t('alterna rectas, frenadas fuertes y curvas lentas con secciones de velocidad media y rápida. La curva 10 es especialmente delicada: se frena cuesta abajo para una izquierda cerrada y con peralte adverso; la 12 es rápida.'), t('las rectas favorecen la eficiencia aerodinámica, mientras las curvas lentas y sus salidas exigen estabilidad y tracción. El asfalto es muy rugoso y favorece el sobrecalentamiento de los neumáticos; Brembo sitúa Sakhir entre los circuitos más exigentes para los frenos.'), [['title' => 'Fórmula 1 — Baréin', 'url' => 'https://www.formula1.com/en/racing/2025/bahrain', 'accessedAt' => '2026-11-08'], ['title' => 'McLaren — asfalto y neumáticos', 'url' => 'https://www.mclaren.com/racing/formula-1/2025/chinese-grand-prix/the-chinese-gp-briefing-powered-by-google-cloud/', 'accessedAt' => '2026-11-08'], ['title' => 'Brembo — exigencia de frenos', 'url' => 'https://www.brembo.com/es/motorsport/formula1/circuitos-desafiantes', 'accessedAt' => '2026-11-08']]],
    'saudi-arabia-jeddah' => ['6,174', 27, t('Media-baja'), t('urbano y muy rápido, con numerosas curvas enlazadas entre muros y frenadas para giros más cerrados. Fórmula 1 lo describe como uno de los trazados más rápidos del calendario.'), t('las rectas y las curvas rápidas obligan a equilibrar resistencia aerodinámica y estabilidad. La proximidad de los muros reduce el margen de error y las frenadas fuertes requieren precisión; Brembo incluye Yeda entre los trazados exigentes para los frenos.'), [['title' => 'Fórmula 1 — Yeda', 'url' => 'https://www.formula1.com/en/racing/2025/saudi-arabia', 'accessedAt' => '2026-11-08'], ['title' => 'Brembo — exigencia de frenos', 'url' => 'https://www.brembo.com/es/motorsport/formula1/circuitos-desafiantes', 'accessedAt' => '2026-11-08']]],
    'miami' => ['5,412', 19, t('Media'), t('combina tres rectas con curvas de distinta velocidad. Entre las curvas 13 y 16 hay cambios de altura y una chicane con subida, cresta y bajada; el resto de la vuelta incluye zonas rápidas y frenadas fuertes.'), t('la velocidad en las rectas se equilibra con el control en el sector estrecho y la estabilidad en los cambios de dirección. El asfalto se renovó en 2023 y el agarre aumenta conforme la pista se engoma durante el fin de semana.'), [['title' => 'Fórmula 1 — Miami', 'url' => 'https://www.formula1.com/en/racing/2025/miami', 'accessedAt' => '2026-11-08'], ['title' => 'Pirelli — asfalto y agarre', 'url' => 'https://cdn.connectsites.net/user_files/f4/downloads/000/075/544/Saturday%20May%203%20Miami%20GP%20Final%20pdf.pdf?1746282734=', 'accessedAt' => '2026-11-08'], ['title' => 'OverTake — guía de curvas', 'url' => 'https://www.overtake.gg/news/f1-25-track-guides.3245/?full=1', 'accessedAt' => '2026-11-08']]],
    'canada-montreal' => ['4,361', 14, t('Media-baja'), t('rápido y de frenada-aceleración, con rectas separadas por chicanes y una horquilla. Las frenadas son fuertes y la chicane final pasa muy cerca del Muro de los Campeones.'), t('Fórmula 1 lo describe como un circuito de baja carga aerodinámica. La velocidad en recta tiene mucho peso, pero también se necesita estabilidad al frenar, capacidad para negociar los pianos y tracción al salir de la horquilla.'), [['title' => 'Fórmula 1 — Montreal', 'url' => 'https://www.formula1.com/en/racing/2025/canada', 'accessedAt' => '2026-11-08'], ['title' => 'Brembo — exigencia de frenos', 'url' => 'https://www.brembo.com/es/motorsport/formula1/circuitos-desafiantes', 'accessedAt' => '2026-11-08']]],
    'monaco' => ['3,337', 19, t('Alta'), t('urbano, estrecho y muy revirado, con curvas lentas, desniveles y barreras próximas. También tiene secciones más rápidas, como la chicane de la Piscina, pero pocas rectas largas.'), t('se priorizan la capacidad de giro y el control; los equipos usan configuraciones de alta carga. La tracción a baja velocidad y la precisión junto a los muros son importantes. Brembo señala que se frena muchas veces por vuelta, aunque no todas las frenadas tienen la misma intensidad.'), [['title' => 'Fórmula 1 — Mónaco', 'url' => 'https://www.formula1.com/en/racing/2025/monaco', 'accessedAt' => '2026-11-08'], ['title' => 'FIA — modificaciones de los coches para Mónaco 2025', 'url' => 'https://www.fia.com/system/files/decision-document/2025_monaco_grand_prix_-_car_presentation_submissions.pdf', 'accessedAt' => '2026-11-08'], ['title' => 'Brembo', 'url' => 'https://www.brembo.com/es/motorsport/formula1/circuitos-desafiantes', 'accessedAt' => '2026-11-08']]],
    'catalunya-barcelona' => ['4,657', 14, t('Media-alta'), t('combina curvas lentas y rápidas, con apoyos prolongados como la curva 3 y una recta principal larga. El trazado permite evaluar tanto el equilibrio en curva rápida como la respuesta en giros más lentos.'), t('el apoyo es importante en las curvas largas, mientras la recta requiere eficiencia. Las cargas laterales y la sucesión de curvas influyen en el trabajo de los neumáticos.'), [['title' => 'Fórmula 1 — Barcelona', 'url' => 'https://www.formula1.com/en/racing/2025/spain', 'accessedAt' => '2026-11-08'], ['title' => 'guía técnica del GP de España', 'url' => 'https://tracinginsights.com/blog/742879/all-you-need-to-know-2025-spanish-grand-prix/', 'accessedAt' => '2026-11-08']]],
    'austria-spielberg' => ['4,318', 10, t('Media'), t('vuelta corta con fuertes desniveles. La primera mitad une rectas y curvas a derechas cuesta arriba; la segunda desciende por una secuencia de curvas rápidas.'), t('las rectas favorecen la velocidad punta y las curvas rápidas requieren estabilidad. Las primeras frenadas se suceden con poco espacio entre ellas; Brembo destaca su intensidad y la exigencia para los frenos.'), [['title' => 'Fórmula 1 — Austria', 'url' => 'https://www.formula1.com/en/racing/2025/austria', 'accessedAt' => '2026-11-08'], ['title' => 'Brembo — frenadas', 'url' => 'https://www.brembo.com/es/motorsport/formula1/circuitos-desafiantes', 'accessedAt' => '2026-11-08']]],
    'great-britain-silverstone' => ['5,891', 18, t('Media-alta'), t('uno de los circuitos más rápidos, con secuencias de cambios de dirección como Maggots y Becketts, curvas de gran velocidad y algunas zonas más lentas.'), t('el paso por curva rápida exige apoyo y estabilidad, mientras las rectas premian la eficiencia. Los neumáticos soportan cargas laterales importantes; Brembo lo sitúa entre los circuitos menos exigentes para los frenos.'), [['title' => 'Fórmula 1 — Silverstone', 'url' => 'https://www.formula1.com/en/racing/2025/great-britain', 'accessedAt' => '2026-11-08'], ['title' => 'Brembo', 'url' => 'https://www.brembo.com/es/motorsport/formula1/circuitos-desafiantes', 'accessedAt' => '2026-11-08']]],
    'belgium-spa' => ['7,004', 19, t('Media-baja'), t('largo y rápido, con grandes desniveles, rectas extensas y curvas de alta velocidad. Eau Rouge y Raidillon encadenan cambios de dirección en subida; el sector central concentra curvas rápidas y la vuelta termina con una chicane lenta.'), t('los sectores de rectas favorecen poca resistencia, mientras el sector central recompensa el apoyo aerodinámico. La meteorología puede variar de una zona a otra; las frenadas y la tracción también son relevantes.'), [['title' => 'Fórmula 1 — Spa', 'url' => 'https://www.formula1.com/en/racing/2025/belgium', 'accessedAt' => '2026-11-08'], ['title' => 'Fórmula 1 — compromiso entre carga y rectas', 'url' => 'https://www.formula1.com/en/latest/article/the-risk-perspective-how-f1-drivers-engineers-and-strategists-tackle-the-spa-francorchamps-circuit.4TNjhNBBeh9ZD6wygCJfwo', 'accessedAt' => '2026-11-08'], ['title' => 'Brembo', 'url' => 'https://www.brembo.com/es/motorsport/formula1/circuitos-desafiantes', 'accessedAt' => '2026-11-08']]],
    'hungary-budapest' => ['4,381', 14, t('Alta'), t('estrecho y revirado, con muchas curvas enlazadas y pocas rectas. Mantener el ritmo entre giros consecutivos es una característica central de la vuelta.'), t('Fórmula 1 señala que los equipos utilizan niveles de carga comparables a los de Mónaco. El agarre y la respuesta del coche en curva tienen más peso que la velocidad punta en rectas cortas.'), [['title' => 'Fórmula 1 — Hungaroring', 'url' => 'https://www.formula1.com/en/racing/2025/hungary', 'accessedAt' => '2026-11-08'], ['title' => 'FIA — configuraciones específicas recogidas por Pit Trace', 'url' => 'https://pit-trace.com/circuits/hungaroring', 'accessedAt' => '2026-11-08']]],
    'netherlands-zandvoort' => ['4,259', 14, t('Alta'), t('rápido y fluido, con desniveles y curvas peraltadas. Hugenholtz y la última curva, Arie Luyendijk, destacan por su peralte; la vuelta encadena curvas con poco descanso.'), t('el apoyo y la estabilidad son importantes en las curvas enlazadas y los peraltes. El trazado somete a los neumáticos a esfuerzos laterales sostenidos.'), [['title' => 'Fórmula 1 — Zandvoort', 'url' => 'https://www.formula1.com/en/racing/2025/netherlands', 'accessedAt' => '2026-11-08'], ['title' => 'Pit Trace — exigencias del circuito', 'url' => 'https://pit-trace.com/circuits/circuit-zandvoort', 'accessedAt' => '2026-11-08']]],
    'monza' => ['5,793', 11, t('Baja'), t('muy rápido, con rectas largas, frenadas fuertes para chicanes cerradas y curvas rápidas como la Parabolica. La recta principal mide aproximadamente 1,1 km.'), t('la velocidad punta favorece configuraciones de baja carga. Las chicanes exigen frenada estable y buena salida; Brembo clasifica Monza entre los circuitos más exigentes para los frenos. Su superficie es lisa y de baja exigencia energética para los neumáticos.'), [['title' => 'Fórmula 1 — Monza', 'url' => 'https://www.formula1.com/en/racing/2025/italy', 'accessedAt' => '2026-11-08'], ['title' => 'Mercedes — superficie y neumáticos', 'url' => 'https://www.mercedesamgf1.com/news/what-are-the-tyre-options-for-the-2026-italian-gp', 'accessedAt' => '2026-11-08'], ['title' => 'Brembo', 'url' => 'https://www.brembo.com/es/motorsport/formula1/circuitos-desafiantes', 'accessedAt' => '2026-11-08'], ['title' => 'FIA — modificaciones específicas recogidas por Pit Trace', 'url' => 'https://pit-trace.com/circuits/monza-circuit', 'accessedAt' => '2026-11-08']]],
    'madrid' => ['5,474', 22, t('Alta'), t('combina zonas rápidas, curvas estrechas, desniveles y una parte final técnica. La curva 12, La Monumental, es larga y peraltada; después se enlazan tramos rápidos y una zona más revirada entre muros.'), t('la parte técnica favorece el apoyo y el control, mientras las zonas rápidas requieren eficiencia. Pirelli destaca las altas cargas verticales en La Monumental y la exigencia lateral del conjunto; el juego incluye una representación de este circuito en el paquete de 2026.'), [['title' => 'Fórmula 1 — guía del Madring', 'url' => 'https://www.formula1.com/en/latest/article/circuit-guide-everything-you-need-to-know-about-the-madring.NF7Mh3iag3w9GUPlihwJA', 'accessedAt' => '2026-11-08'], ['title' => 'Pirelli — exigencias de neumáticos', 'url' => 'https://www.formula1.com/en/latest/article/what-tyres-will-the-teams-and-drivers-have-for-the-2026-spanish-grand-prix.2vlcVOBnZUFRCooVcqWG7n', 'accessedAt' => '2026-11-08'], ['title' => 'EA — guía del circuito en el juego', 'url' => 'https://www.ea.com/games/f1/f1-25/news/f1-25-2026-season-edition-madring-tips-and-tricks', 'accessedAt' => '2026-11-08']]],
    'azerbaijan-baku' => ['6,003', 20, t('Baja'), t('contrasta una recta principal muy larga con curvas lentas y una sección estrecha junto a la ciudad antigua. La primera curva llega después de una frenada desde alta velocidad.'), t('Fórmula 1 identifica la elección entre apoyo en la zona revirada y menor resistencia en la recta. La frenada fuerte y la salida de curvas lentas son importantes; los muros castigan los errores.'), [['title' => 'Fórmula 1 — Bakú', 'url' => 'https://www.formula1.com/en/racing/2025/azerbaijan', 'accessedAt' => '2026-11-08'], ['title' => 'Brembo', 'url' => 'https://www.brembo.com/es/motorsport/formula1/circuitos-desafiantes', 'accessedAt' => '2026-11-08']]],
    'singapore' => ['4,927', 19, t('Alta'), t('urbano y revirado, con numerosas curvas entre muros, asfalto irregular y frenadas frecuentes. La modificación de 2023 redujo el número de curvas, pero sigue siendo exigente físicamente y para la tracción.'), t('el agarre y la respuesta en las curvas pesan mucho en relación con la velocidad punta. Las salidas sucesivas pueden elevar la temperatura de los neumáticos traseros y el asfalto irregular influye en la estabilidad.'), [['title' => 'Fórmula 1 — Singapur', 'url' => 'https://www.formula1.com/en/racing/2025/singapore', 'accessedAt' => '2026-11-08'], ['title' => 'Fórmula 1 — guía técnica', 'url' => 'https://www.formula1.com/en/latest/article/circuit-guide-everything-you-need-to-know-about-the-marina-bay-street-circuit.3d9yfiqIKoQhcMnRLESWbz.3d9yfiqIKoQhcMnRLESWbz', 'accessedAt' => '2026-11-08'], ['title' => 'Brembo', 'url' => 'https://www.brembo.com/es/motorsport/formula1/circuitos-desafiantes', 'accessedAt' => '2026-11-08']]],
    'texas-austin' => ['5,513', 20, t('Media-alta'), t('variado, con una subida pronunciada a la primera curva, eses rápidas en el primer sector, una recta larga y una sección técnica posterior. Las curvas 3 a 6 recuerdan a las secuencias rápidas de Silverstone y Suzuka.'), t('las eses y curvas enlazadas requieren apoyo y cambios de dirección estables; la recta larga favorece la velocidad punta. Pirelli destaca tanto el esfuerzo lateral como la tracción y el trabajo de los neumáticos.'), [['title' => 'Fórmula 1 — Austin', 'url' => 'https://www.formula1.com/en/racing/2025/united-states', 'accessedAt' => '2026-11-08'], ['title' => 'Pirelli — ficha previa de 2025', 'url' => 'https://cdn.connectsites.net/user_files/f4/downloads/000/077/861/2025%20USGP%202%20Saturday%20October%2018%20Final%20pdf.pdf?1760741645=', 'accessedAt' => '2026-11-08']]],
    'mexico' => ['4,304', 17, t('Media-alta'), t('combina una recta principal larga con frenadas y una sección técnica que atraviesa el estadio. El circuito está situado a más de 2.000 metros de altitud.'), t('la baja densidad del aire reduce la carga generada y afecta a la refrigeración; la recta y el sector técnico plantean necesidades diferentes. Brembo incluye Ciudad de México entre los circuitos de alta exigencia para los frenos.'), [['title' => 'Fórmula 1 — México', 'url' => 'https://www.formula1.com/en/racing/2025/mexico', 'accessedAt' => '2026-11-08'], ['title' => 'Fórmula 1 — efectos de la altitud', 'url' => 'https://www.formula1.com/en/latest/article/the-risk-perspective-how-f1-drivers-engineers-and-strategists-tackle-the-mexico-city-grand-prix.B8P8xr5i1sPDgQOmL7hzs', 'accessedAt' => '2026-11-08'], ['title' => 'Brembo', 'url' => 'https://www.brembo.com/es/motorsport/formula1/circuitos-desafiantes', 'accessedAt' => '2026-11-08']]],
    'brazil-interlagos' => ['4,309', 15, t('Media'), t('corto y con desniveles, comienza con las eses de Senna, continúa por una sección interior enlazada y termina con una subida prolongada hacia la recta de meta.'), t('el sector interior requiere agarre en curvas enlazadas; la larga subida da importancia a la aceleración y la eficiencia en recta. Williams destaca la tracción a la salida de la curva 12 y el riesgo de bloqueo en varias frenadas.'), [['title' => 'Fórmula 1 — Interlagos', 'url' => 'https://www.formula1.com/en/racing/2025/brazil', 'accessedAt' => '2026-11-08'], ['title' => 'Williams — análisis técnico de São Paulo', 'url' => 'https://www.williamsf1.com/articles/b58ad6ed-d4b8-4ca6-857d-95f26dee244c/technical-brief-sao-paulo', 'accessedAt' => '2026-11-08']]],
    'las-vegas' => ['6,201', 17, t('Baja'), t('urbano y muy rápido, con rectas largas y frenadas para curvas cerradas. Fórmula 1 compara su velocidad media con la de Monza.'), t('las rectas favorecen poca resistencia aerodinámica; las frenadas y aceleraciones desde baja velocidad requieren control. Las bajas temperaturas pueden dificultar el funcionamiento de los neumáticos.'), [['title' => 'Fórmula 1 — Las Vegas', 'url' => 'https://www.formula1.com/en/racing/2025/las-vegas', 'accessedAt' => '2026-11-08'], ['title' => 'Pirelli — condiciones y neumáticos', 'url' => 'https://cdn.connectsites.net/user_files/f4/downloads/000/070/211/Thursday%202023%20Las%20Vegas%20GP%20newsletter%20final%20pdf.pdf?1700269693=', 'accessedAt' => '2026-11-08'], ['title' => 'Brembo', 'url' => 'https://www.brembo.com/es/motorsport/formula1/circuitos-desafiantes', 'accessedAt' => '2026-11-08']]],
    'qatar-lusail' => ['5,419', 16, t('Alta'), t('rápido y fluido; predominan las curvas medias y rápidas, con una recta principal de más de un kilómetro. Las curvas enlazadas mantienen al coche en apoyo durante buena parte de la vuelta.'), t('el apoyo en curva y la estabilidad lateral deben convivir con la velocidad en la recta. Las curvas rápidas exigen mucho a los neumáticos; Brembo señala que hay pocas frenadas de intensidad máxima.'), [['title' => 'Fórmula 1 — Lusail', 'url' => 'https://www.formula1.com/en/racing/2025/qatar', 'accessedAt' => '2026-11-08'], ['title' => 'Brembo', 'url' => 'https://www.brembo.com/es/motorsport/formula1/circuitos-desafiantes', 'accessedAt' => '2026-11-08']]],
    'abu-dhabi' => ['5,281', 16, t('Media'), t('una horquilla lenta desemboca en una recta de 1,2 km, seguida de otra frenada importante. El resto combina curvas enlazadas y una sección final técnica; las modificaciones de 2021 alteraron varias curvas lentas.'), t('la aceleración a la salida de la horquilla y la velocidad en recta compiten con el agarre necesario en el resto de la vuelta. Hay frenadas con el coche todavía sometido a carga lateral.'), [['title' => 'Fórmula 1 — Yas Marina', 'url' => 'https://www.formula1.com/en/racing/2025/united-arab-emirates', 'accessedAt' => '2026-11-08'], ['title' => 'OverTake — guía de curvas', 'url' => 'https://www.overtake.gg/news/f1-25-track-guides.3245/?full=1', 'accessedAt' => '2026-11-08']]],
    'imola' => ['4,909', 19, t('Media-alta'), t('rápido y técnico, con chicanes, curvas como Piratella y Acque Minerali, y cambios de altura. Acque Minerali combina una entrada rápida con una frenada para un giro cerrado antes de subir hacia la chicane de Variante Alta.'), t('las curvas rápidas requieren estabilidad y apoyo; las chicanes y las zonas de aceleración exigen buen control sobre los pianos y tracción. La combinación obliga a equilibrar agilidad y velocidad en recta.'), [['title' => 'Fórmula 1 — Imola', 'url' => 'https://www.formula1.com/en/racing/2025/emiliaromagna', 'accessedAt' => '2026-11-08'], ['title' => 'OverTake — guía de curvas', 'url' => 'https://www.overtake.gg/news/f1-25-track-guides.3245/?full=1', 'accessedAt' => '2026-11-08']]],
];
